def search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

assert search([1, 2, 3], 2) == 1
assert search([1, 2, 3], 0) == -1
assert search([1, 2, 3], 3) == 2
